begin;
select no_plan();
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
insert into cooksmith.household_recipes(id,household_id,name,measurement_system) values('a0000000-0000-4000-8000-000000000079','20000000-0000-4000-8000-000000000001','Measured recipe','au');
select is((select measurement_system from cooksmith.household_recipes where id='a0000000-0000-4000-8000-000000000079'),'au','Recipe convention persists under existing household RLS');
select throws_ok($$update cooksmith.household_recipes set measurement_system='guess' where id='a0000000-0000-4000-8000-000000000079'$$,'23514',null,'Unsupported conventions are rejected');
insert into cooksmith.planned_meals(id,household_id,meal_date,meal_type,title,recipe_id) values('80000000-0000-4000-8000-000000000080','20000000-0000-4000-8000-000000000001','2026-10-04','dinner','Measured meal','a0000000-0000-4000-8000-000000000079');
select cooksmith.reconcile_planned_meal_shopping('20000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000080','[{"name":"plain flour","quantity":150,"unit":"g","category":"pantry","sourceQuantities":[{"name":"plain flour","quantity":"1","unit":"cup","purchaseUnit":"g","measurementSystem":"au","approximate":true,"conversionId":"taste-plain-flour-v1"}]}]');
select is((select source_quantities->0->>'conversionId' from cooksmith.shopping_item_contributions where planned_meal_id='80000000-0000-4000-8000-000000000080'),'taste-plain-flour-v1','Versioned conversion provenance survives persistence');
select ok(not (select combine_with_plan from cooksmith.shopping_list_items where display_name='plain flour'),'Opt-in defaults to false');
select cooksmith.update_shopping_purchase('20000000-0000-4000-8000-000000000001',(select jsonb_agg(jsonb_build_object('id',id,'name',display_name,'quantity',200,'unit','g','category','pantry','measurementSystem','au')) from cooksmith.shopping_list_items where display_name='plain flour'));
select cooksmith.reconcile_planned_meal_shopping('20000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000080','[{"name":"plain flour","quantity":144,"unit":"g","category":"pantry","sourceQuantities":[{"name":"plain flour","quantity":"1","unit":"cup","purchaseUnit":"g","measurementSystem":"us","approximate":true,"conversionId":"taste-plain-flour-v1"}]}]');
select ok((select combine_with_plan from cooksmith.shopping_list_items where display_name='plain flour'),'Explicit planned purchase editing retains combined override intent');
select is((select sum(quantity) from cooksmith.shopping_list_items where display_name='plain flour'),200::numeric,'Changing recipe convention retains the family purchase override without duplication');
select is((select count(*)::integer from cooksmith.shopping_list_items where display_name='plain flour'),1,'Recipe retry does not create a second purchase');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
select is((select count(*)::integer from cooksmith.household_recipes where id='a0000000-0000-4000-8000-000000000079'),0,'Another household cannot read the private recipe convention');
update cooksmith.household_recipes set measurement_system='us' where id='a0000000-0000-4000-8000-000000000079';
select throws_ok($$select cooksmith.reconcile_planned_meal_shopping('20000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000080','[]')$$,'42501',null,'Another household cannot reconcile converted amounts');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select is((select measurement_system from cooksmith.household_recipes where id='a0000000-0000-4000-8000-000000000079'),'au','Cross-household update changed no recipe');
select is(cooksmith.purchase_unit_v3('tsp.'),'tsp','Unknown teaspoon stays a teaspoon');
select is(cooksmith.purchase_unit_multiplier_v3('kg'),1000::numeric,'Exact metric scale conversion still applies');
reset role;
select ok(not has_function_privilege('anon','cooksmith.purchase_unit_v3(text)','EXECUTE'),'Anonymous helper access is not granted');
select * from finish();
rollback;
